import { host } from "../host.mjs";
/** The installed host validates its own receipt; request data cannot implement this port. */
export function acceptedOperationSourceBytes(receipt, request, command, workspace) {
  const operation = host().sourceOperation;
  if (!operation || typeof operation.acceptedSources !== 'function') throw new Error('MissingSourceOperationHost');
  return operation.acceptedSources(receipt, request, command, workspace);
}

/** Resolution is a host identity operation; this function grants no effect authority. */
export function sourceOperationModuleURL(specifier, parent) {
  const operation = host().sourceOperation;
  if (!operation || typeof operation.moduleURL !== 'function') throw Error('MissingSourceModuleIdentityHost');
  return operation.moduleURL(specifier, parent);
}

/** Only a host receipt captured while the exact candidate existed can certify verification. */
export function acceptedOperationCandidateStatus(receipt, request, command, workspace, destination, identity) {
  const operation = host().sourceOperation;
  if (!operation || typeof operation.finalizedCandidateStatus !== 'function') throw Error('MissingCandidateOperationHost');
  return operation.finalizedCandidateStatus(receipt, request, command, workspace, destination, identity);
}

/** Reversible authoring only under an actual host-owned single-writer lease. */
export function createCandidateTransaction(io, path, identity) {
  if (!io.ownsLease()) throw new Error('MissingSingleWriterLease');
  if (io.inspect(path).kind !== 'absent') throw new Error('UnownedExistingDestination');
  let phase = 'prepared';
  const unchanged = () => {
    const state = io.inspect(path);
    return state.kind === 'file' && state.identity === identity;
  };
  return Object.freeze({
    authorizeWrite() {
      if (phase !== 'prepared') throw new Error('InvalidCandidatePhase');
      if (!io.ownsLease()) throw new Error('MissingSingleWriterLease');
      if (io.inspect(path).kind !== 'absent') throw new Error('UnownedExistingDestination');
      return {
        state: phase,
        authorized: true
      };
    },
    recordWrite() {
      if (!io.ownsLease()) throw new Error('MissingSingleWriterLease');
      if (phase !== 'prepared') throw new Error('InvalidCandidatePhase');
      if (!unchanged()) throw new Error('UnobservedCandidateWrite');
      phase = 'written';
      return {
        state: phase,
        removed: false
      };
    },
    abort() {
      if (phase !== 'written') throw new Error('InvalidCandidatePhase');
      if (!io.ownsLease()) throw new Error('MissingSingleWriterLease');
      if (!unchanged()) {
        phase = 'refused-drift';
        return {
          state: phase,
          removed: false
        };
      }
      const removed = io.removeUnchangedCandidate(path, identity);
      phase = removed ? 'rolled-back' : 'refused-drift';
      return {
        state: phase,
        removed,
        processDisposition: 'unverified'
      };
    },
    finish(receipt) {
      if (phase !== 'written') throw new Error('InvalidCandidatePhase');
      if (!io.ownsLease()) throw new Error('MissingSingleWriterLease');
      const disposition = io.processDisposition(receipt);
      if (!['succeeded', 'failed', 'incomplete'].includes(disposition)) throw new Error('UnownedProcessDisposition');
      if (!unchanged()) {
        phase = 'refused-drift';
        return {
          state: phase,
          removed: false
        };
      }
      if (disposition === 'succeeded') {
        phase = 'committed';
        return {
          state: phase,
          removed: false
        };
      }
      const removed = io.removeUnchangedCandidate(path, identity);
      phase = removed ? 'rolled-back' : 'refused-drift';
      return {
        state: phase,
        removed
      };
    }
  });
}

function requireCondition(value, message = 'UnboundSourceContract') {
  if (!value) throw Error(message);
}
const invariant = Object.freeze({
  ok: requireCondition,
  equal(left, right, message) {
    requireCondition(Object.is(left, right), message);
  },
  notEqual(left, right, message) {
    requireCondition(!Object.is(left, right), message);
  }
});
export default invariant;

import { sourceContractDiagnostic } from "./source-contract-diagnostics.mjs";
import assert from "./source-invariants.mjs";
import { sourceOperationModuleURL as moduleURL } from "./source-operation-port.mjs";
import { observeSourceCallables } from "./callable_catalog.mjs";
import { sha256Hex } from "../crate/source_fetch.mjs";

/** Static source evidence binds reuse within one already-authorized Node operation; it does not prove initializer purity. */
export function bindAcceptedImport(acceptance, source, binding, operation) {
  assert.equal(operation.command, 'node --test ' + operation.acceptanceOperand, 'different operation');
  assert.equal(operation.acceptancePath, acceptance.path, 'foreign acceptance');
  assert.equal(operation.acceptanceIdentity, sha256Hex(acceptance.content), 'acceptance drift');
  assert.equal(binding.contentId, sha256Hex(source.content), 'source drift');
  const catalog = observeSourceCallables(acceptance.content, acceptance.path);
  assert.ok(!catalog.gaps.some(gap => ['LexicalFailure', 'DuplicateBinding', 'DuplicateExport'].includes(gap.reason)), 'ambiguous acceptance');
  const sourceCatalog = observeSourceCallables(source.content, source.path);
  const exported = sourceCatalog.exports.filter(value => value.exposed === binding.exported);
  assert.equal(exported.length, 1, 'unproved export');
  const declaration = sourceCatalog.declarations.find(value => value.name === exported[0].local);
  assert.ok(declaration, 'unobserved declaration');
  const expected = moduleURL(binding.specifier, acceptance.path);
  assert.equal(expected, moduleURL(source.path, acceptance.path), sourceContractDiagnostic("source-module-url-mismatch"));
  const matches = catalog.imports.filter(value => moduleURLOrNull(value.specifier, acceptance.path) === expected && value.bindings.some(name => name.imported === binding.exported));
  assert.equal(matches.length, 1, sourceContractDiagnostic("unaccepted-module-import"));
  return Object.freeze({
    kind: 'accepted-operation-import-reuse',
    moduleURL: expected,
    exported: binding.exported,
    sourceIdentity: binding.contentId,
    acceptanceIdentity: catalog.contentId,
    operation: operation.command,
    additionalModuleInitialization: false,
    moduleEffects: sourceCatalog.moduleEffects,
    callEffects: 'conditional',
    scope: 'same-operation-same-module-URL',
    rustEquivalence: 'unknown'
  });
}
function moduleURLOrNull(specifier, parent) {
  try {
    return moduleURL(specifier, parent);
  } catch {
    return null;
  }
}

import { sourceContractDiagnostic } from "./source-contract-diagnostics.mjs";
import { observedCallableRequest, signature } from "../module_function.mjs";
import { sentences } from "../shell_command_policy.mjs";
import { parseLinoRoot, findChildValue } from "../write_lino.mjs";
import { sourceEvidence } from "./source_contract.mjs";
import { sha256Hex } from "../crate/source_fetch.mjs";
import { sourceGoalScope } from "./seeded-composition-hook.mjs";
const kinds = ['declaration', 'goal', 'source-discovery', 'reuse-imports', 'read-prerequisites', 'repair-plan', 'verification', 'protect-inputs', 'gap-before-write'];
/** Source-bound finite grammar; its goal and effect obligations are still separately checked. */
export function deriveCompleteSourceRequest(text, seed) {
  const scope = sourceGoalScope(text),
    request = observedCallableRequest(text);
  if (scope === null || request === null) return null;
  const root = parseLinoRoot(seed).children.find(node => node.name === 'source-request-preflight');
  if (!root) return null;
  const forms = root.children.filter(node => node.name === 'form');
  if (forms.length !== kinds.length || !kinds.every(kind => forms.filter(form => form.id === kind).length === 1)) return null;
  const clauses = [];
  const encoder = new TextEncoder();
  for (const sentence of sentences(scope)) {
    const matches = forms.flatMap(form => {
      let match;
      try {
        match = new RegExp(findChildValue(form, 'pattern'), 'iu').exec(sentence.text);
      } catch {
        return [];
      }
      return match && match[0] === sentence.text ? [{
        kind: form.id,
        captures: {
          ...match.groups
        }
      }] : [];
    });
    if (matches.length !== 1) return null;
    const item = matches[0],
      capture = item.captures;
    if (item.kind === 'declaration') {
      const observed = signature(capture.signature);
      if (!observed || observed.at !== 0 || !capture.signature.endsWith(')') || observed.name !== request.name || JSON.stringify(observed.parameters) !== JSON.stringify(request.parameters) || capture.destination !== request.destination) return null;
    }
    if (item.kind === 'source-discovery' && capture.sources !== request.inputs.join(findChildValue(root, 'source-joiner'))) return null;
    if (item.kind === 'verification' && (request.acceptance.length !== 1 || capture.acceptance !== request.acceptance[0] || capture.command !== request.command)) return null;
    const start = encoder.encode(scope.slice(0, sentence.span.start)).length;
    const end = encoder.encode(scope.slice(0, sentence.span.end)).length;
    clauses.push({
      ...item,
      sentence: sentence.text,
      evidence: sourceEvidence(text, start, end),
      status: 'requires-contract'
    });
  }
  if (!kinds.every(kind => clauses.filter(clause => clause.kind === kind).length === 1)) return null;
  return {
    request,
    requestIdentity: sha256Hex(text),
    seedIdentity: sha256Hex(seed),
    clauses,
    syntaxCoverage: 'complete-finite-seeded-forms',
    semanticAuthority: false,
    writeAuthority: false
