        const eventPrefix = template('plan-event-append-command')?.split('{lock_path}')[0];
        if (resolve(dir) === REPOSITORY_ROOT && eventPrefix && args.command.startsWith(eventPrefix)) {
          mkdirSync(PLAN_EVENTS_SANDBOX, { recursive: true });
          eventDirectory = mkdtempSync(join(tmpdir(), 'formal-ai-plan-events-'));
          symlinkSync(PLAN_EVENTS_SANDBOX, join(eventDirectory, '.formal-ai'), process.platform === 'win32' ? 'junction' : 'dir');
          commandDirectory = eventDirectory;
        }
        try {
          return shellCapture(args.command, {cwd:commandDirectory, timeoutMs:BASH_TIMEOUT_MS});
        } finally {
          if (eventDirectory !== null) rmSync(eventDirectory, { recursive: true, force: true });
        }
      }
      case 'list':
        return readdirSync(within(dir, path ?? '.')).join('\n');
      case 'grep':
        return grep(dir, args);
      default:
        return toolFailure(`the dogfood driver does not execute ${call.tool}`);
    }
  } catch (error) {
    return toolFailure(error.message);
  }
}

/**
 * Run a whole session; returns `{transcript, answer, stop}`. `answer` is null
 * when the session ends without one, and `stop` then says why: `no-plan` (the
 * planner and its fall-through planned nothing) or `steps` (the step budget
 * ran out mid-task, PR #1188 G84).
 */
export async function drive(planChatStep, dir, prompt, {
  tools = AGENT_CLI_TOOLS, steps = 12, fallthrough = null, allowedCommands = undefined,
  atomicRecordAppend = false,
} = {}) {
  if (!Array.isArray(tools) || new Set(tools).size !== tools.length || tools.some((tool) => !AGENT_CLI_TOOLS.includes(tool))) {
    return { transcript: [], answer: null, stop: 'invalid-tools', toolsAdvertised: [] };
  }
  if (typeof atomicRecordAppend !== 'boolean') {
    return { transcript: [], answer: null, stop: 'invalid-append-policy', toolsAdvertised: tools };
  }
  tools = Object.freeze([...tools]);
  if (allowedCommands !== undefined) {
    if (!Array.isArray(allowedCommands)
        || allowedCommands.some(command => typeof command !== 'string')
        || new Set(allowedCommands).size !== allowedCommands.length) {
      return { transcript: [], answer: null, stop: 'invalid-command-policy', toolsAdvertised: tools };
    }
    allowedCommands = Object.freeze([...allowedCommands]);
  }
  const sourceSession = host().sourceSession;
  if (sourceSession && !sourceSession.active()) {
    return sourceSession.run({ request: prompt, workspace: dir, tools }, () =>
      drive(planChatStep, dir, prompt, { tools, steps, fallthrough, allowedCommands, atomicRecordAppend }));
  }
  const messages = [
    { role: 'system', content: `<env>\n  Working directory: ${dir}\n  Is directory a git repo: yes\n</env>` },
    { role: 'user', content: prompt },
  ];
  const transcript = [];
  for (let step = 0; step < steps; step += 1) {
    // The server's fall-through: no planned step means the solver answers and
    // the symbolic command reroute may still turn that answer into tool calls
    // (js/server/agentic.mjs commandReroutePlan).
    const contracts = atomicRecordAppend && tools.includes('write') ? [appendDefinition('write')] : [];
    const scoped = projectAppendContracts(messages, contracts);
    const plan = (await planChatStep(scoped, tools)) ?? (fallthrough ? await fallthrough(messages, tools) : null);
    if (!plan) return { transcript, answer: null, stop: 'no-plan', toolsAdvertised: tools };
    if (plan.kind === 'final') return { transcript, answer: plan.answer, stop: 'final', toolsAdvertised: tools };
    // Snapshot the complete batch before validation; getters cannot change executed arguments.
    const calls = plan.calls.map(call => Object.freeze({ tool: call.tool, arguments: call.arguments }));
    if (!atomicRecordAppend && calls.some(call => call.tool === 'write'
      && argsOf(call).append_mode !== undefined)) {
      return { transcript, answer: null, stop: 'undeclared-append-contract', toolsAdvertised: tools };
    }
    if (calls.some((call) => !tools.includes(call.tool))) {
      return { transcript, answer: null, stop: 'undeclared-tool', toolsAdvertised: tools };
    }
    if (allowedCommands !== undefined) {
      const deniedCalls = calls.filter(call => {
        if (call.tool !== 'bash') return false;
        try {
          if (typeof call.arguments !== 'string') return true;
          const arguments_ = JSON.parse(call.arguments);
          return !arguments_ || typeof arguments_.command !== 'string'
            || !allowedCommands.includes(arguments_.command);
        } catch {
          return true;
        }
      });
      if (deniedCalls.length) {
        return { transcript, answer: null, stop: 'command-policy-denied',
          toolsAdvertised: tools, deniedCalls };
      }
    }
    const toolCalls = calls.map((call, index) => ({
      id: `c${step}_${index}`, type: 'function', function: { name: call.tool, arguments: call.arguments },
    }));
    messages.push({ role: 'assistant', content: '', tool_calls: toolCalls });
    calls.forEach((call, index) => {
      const receipt = sourceSession
        ? sourceSession.executeResult(call, messages, () => executeResult(dir, call))
        : executeResult(dir, call);
      const { content: result, ...metadata } = receipt;
      transcript.push({ tool: call.tool, arguments: call.arguments, result, ...metadata });
      messages.push({ role: 'tool', tool_call_id: toolCalls[index].id, name: call.tool, ...receipt });
    });
  }
  return { transcript, answer: null, stop: 'steps', toolsAdvertised: tools };
}

/** What the driver prints when a session ends with no answer: never a bare `null`. */
export function unanswered(stop, steps, calls) {
  if (stop === 'steps') return `(no answer: the ${steps}-step budget ran out after ${calls} tool calls, before the task finished; run again with a larger --steps)`;
  return `(no answer: the planner planned no step after ${calls} tool calls)`;
}

async function main(argv) {
  let dir = null;
  let steps = 12;
  const rest = [];
  for (let index = 0; index < argv.length; index += 1) {
    if (argv[index] === '--dir') dir = argv[++index];
    else if (argv[index] === '--steps') steps = Number(argv[++index]);
    else rest.push(argv[index]);
  }
  if (!dir || rest.length === 0) throw new Error('usage: drive.mjs --dir <sandbox> [--steps N] <prompt>');
  await installNodeHost(new WorkerHost());
  const sourceSession = createNodeSourceSessionHost(host().readText);
  installHost({ ...host(), sourceSession, sourceOperation: sourceSession.sourceOperation });
  const { planChatStep } = await import('../../js/agentic/planner.mjs');
  const { solve } = await import('../../js/agentic/host.mjs');
  const { planSymbolicCommandReroute } = await import('../../js/agentic/command_reroute.mjs');
  const { latestUserRequest } = await import('../../js/agentic/content.mjs');
  const fallthrough = async (messages, tools) => {
    const symbolic = await solve(latestUserRequest(messages) ?? '', []);
    return planSymbolicCommandReroute(messages, tools, symbolic) ?? { kind: 'final', answer: symbolic.answer };
  };
  const { transcript, answer, stop } = await drive(planChatStep, resolve(dir), rest.join(' '), { steps, fallthrough });
  const out = [];
  for (const entry of transcript) {
    out.push(`>> ${entry.tool} ${entry.arguments}`);
    if (entry.result) out.push(entry.result.split('\n').map((line) => `   ${line}`).join('\n'));
  }
  out.push(`== answer ==\n${answer ?? unanswered(stop, steps, transcript.length)}`);
  // Flush the complete transcript before exiting, including asynchronous pipe writes.
  await new Promise((complete, fail) => {
    process.stdout.write(`${out.join('\n')}\n`, error => {
      if (error) fail(error);
      else complete();
    });
  });
  process.exit(0);
}

if (import.meta.url === `file://${process.argv[1]}`) await main(process.argv.slice(2));

//! Complete seeded request syntax; semantic goals and host authority remain separate.
use crate::agentic_coding::shell_command_policy::sentences;
use crate::seed::parser::parse_lino;
use crate::source_fetch::sha256_hex;
use serde_json::{Value, json};

pub fn source_goal_scope(source: &str) -> Option<String> {
    if crate::normal_markov::quote_fault(source).is_some() {
        return None;
    }
    let mut result = String::new();
    let mut cursor = 0;
    for span in crate::normal_markov::quoted_segment_spans(source) {
        result.push_str(&source[cursor..span.start]);
        result.push_str(&" ".repeat(span.end - span.start));
        cursor = span.end;
    }
    result.push_str(&source[cursor..]);
    Some(result)
}

pub fn derive_complete_source_request(text: &str, seed: &str) -> Option<Value> {
    let scope = source_goal_scope(text)?;
    let request = super::discovery::observed_callable_request(text)?;
    let parsed = parse_lino(seed);
    let root = parsed
        .children
        .iter()
        .find(|node| node.name == "source-request-preflight")?;
    let kinds = [
        "declaration",
        "goal",
        "source-discovery",
        "reuse-imports",
        "read-prerequisites",
        "repair-plan",
        "verification",
        "protect-inputs",
        "gap-before-write",
    ];
    let forms: Vec<_> = root
        .children
        .iter()
        .filter(|node| node.name == "form")
        .collect();
    if forms.len() != kinds.len()
        || !kinds
            .iter()
            .all(|kind| forms.iter().filter(|form| form.id == *kind).count() == 1)
    {
        return None;
    }
    let mut clauses = Vec::new();
    for sentence in sentences(&scope) {
        let mut matches = Vec::new();
        for form in &forms {
            let pattern = regex::RegexBuilder::new(form.find_child_value("pattern"))
                .case_insensitive(true)
                .build()
                .ok()?;
            let Some(captures) = pattern.captures(sentence.text) else {
                continue;
            };
            if captures.get(0)?.as_str() != sentence.text {
                continue;
            }
            let mut values = serde_json::Map::new();
            for name in pattern.capture_names().flatten() {
                if let Some(value) = captures.name(name) {
                    values.insert(name.to_owned(), json!(value.as_str()));
                }
            }
            matches.push((form.id.as_str(), values));
        }
        if matches.len() != 1 {
            return None;
        }
        let (kind, captures) = matches.pop()?;
        if kind == "declaration" {
            let signature = captures.get("signature")?.as_str()?;
            let observed = super::signature(signature)?;
            if observed.at != 0
                || !signature.ends_with(')')
                || observed.name != request.name
                || observed.parameters != request.parameters
                || captures.get("destination")?.as_str()? != request.destination
            {
                return None;
            }
        }
        if kind == "source-discovery"
            && captures.get("sources")?.as_str()?
                != request.inputs.join(root.find_child_value("source-joiner"))
        {
            return None;
        }
        if kind == "verification"
            && (request.acceptance.len() != 1
                || captures.get("acceptance")?.as_str()? != request.acceptance[0]
                || Some(captures.get("command")?.as_str()?) != request.command.as_deref())
        {
            return None;
        }
        clauses.push(json!({"kind":kind,"captures":captures,"sentence":sentence.text,
            "evidence":super::source_contract::source_evidence(text,sentence.span.start,sentence.span.end),
            "status":"requires-contract"}));
    }
    if !kinds.iter().all(|kind| {
        clauses
            .iter()
            .filter(|clause| clause["kind"] == *kind)
            .count()
            == 1
    }) {
        return None;
    }
    Some(
        json!({"request":{"name":request.name,"parameters":request.parameters,
        "destination":request.destination,"inputs":request.inputs,"acceptance":request.acceptance,
        "command":request.command},"requestIdentity":sha256_hex(text.as_bytes()),
        "seedIdentity":sha256_hex(seed.as_bytes()),"clauses":clauses,
        "syntaxCoverage":"complete-finite-seeded-forms","semanticAuthority":false,"writeAuthority":false}),
    )
}

/// Conditional discharge only; private host receipt validation still precedes every effect.
pub fn bind_complete_source_needs(
    frame: &Value,
    composition: &Value,
    preflight: &Value,
    canonical_sources: &[Value],
) -> Result<Value, &'static str> {
    if frame["requestIdentity"].as_str().is_none()
        || frame["requestIdentity"] != composition["requestIdentity"]
        || preflight["ledger"]["sourceIdentity"] != frame["requestIdentity"]
    {
        return Err("UnboundRequestContracts");
    }
    let prerequisites = preflight["prerequisites"]
        .as_array()
        .ok_or("MissingReadPrerequisites")?;
    if !prerequisites.iter().all(|value| {
        matches!(
            value["status"].as_str(),
            Some("conditional-satisfied-read" | "conditional-satisfied-absence")
        )
    }) {
        return Err("UnsolvedImmutableReadPrerequisite");
    }
    let clauses = frame["clauses"].as_array().ok_or("MissingRequestClauses")?;
    let goal = clauses
        .iter()
        .find(|value| value["kind"] == "goal")
        .ok_or("MissingSourceGoal")?;
    if goal["sentence"] != composition["returnForm"]["sentence"]
        || composition["goalClauseCoverage"] != "complete-seeded-return-form"
    {
        return Err("UnboundSourceGoal");
    }
    let imports = composition["imports"]
        .as_array()
        .ok_or("MissingSourceImports")?;
    if !imports.iter().all(|binding| {
        canonical_sources.iter().any(|source| {
            source["moduleURL"].as_str().is_some()
                && source["moduleURL"] == binding["moduleURL"]
                && source["sha256"].as_str().is_some()
                && source["sha256"] == binding["sourceIdentity"]
        })
    }) {
        return Err("UnboundCanonicalSourceReceipt");
    }
    let effects = &composition["effectPlan"];
    if effects["kind"] != "checked-source-import-composition"
        || effects["localMutation"] != false
        || effects["additionalModuleInitialization"] != false
    {
        return Err("UnboundImportedImplementationOwnership");
    }
    Ok(
        json!({"requestIdentity":frame["requestIdentity"],"clauses":clauses,
        "readPrerequisites":prerequisites,"boundedRepairPlan":{"graph":composition["graph"],
        "imports":imports,"effects":effects},"pending":[{"kind":"verification",
        "command":frame["request"]["command"]},{"kind":"protected-input-byte-recheck"}],
        "allowedDestination":frame["request"]["destination"],"allowedCommand":frame["request"]["command"],
        "candidateWriteAuthority":"conditional-reversible-draft-only","unconditionalDeliveryAuthority":false,
        "sourceEffects":"conditional","moduleInitialization":"inherited same provider-approved Node operation; not purity",
        "loadedByteRaceProof":false,"autonomousCredit":0}),
    )
}

//! Conditional request-derived prerequisites, without semantic write authority.
use super::discovery::{observed_callable_goal_ledger, observed_callable_request};
use crate::agentic_coding::tool_result::SourceReadStatus;
use crate::agentic_coding::{file_read, planner, progress::Progress, workspace_change};
use crate::protocol::ChatMessage;
use serde_json::{Value, json};

/// Mirrors sourceNeedPreflight; actual host message ownership remains required.
pub fn source_need_preflight(source: &str, messages: &[ChatMessage]) -> Option<Value> {
    if crate::normal_markov::quote_fault(source).is_some() {
        return None;
    }
    let user = messages
        .iter()
        .rev()
        .find(|message| message.role == "user")?;
    if user.content.user_request_text() != source {
        return None;
    }
    let request = observed_callable_request(source)?;
    let ledger = observed_callable_goal_ledger(&request, messages);
    let progress = Progress::scan(messages);
    let operands = std::iter::once((&request.destination, "destination"))
        .chain(request.inputs.iter().map(|path| (path, "source")))
        .chain(request.acceptance.iter().map(|path| (path, "acceptance")));
    let prerequisites = operands.map(|(path, role)| {
        let policy = file_read::read_policy_blocks_plan(source,
            &planner::plan_one("read", workspace_change::read_arguments(path)));
        let read = progress.source_read_for(path);
        let status = if policy { "policy-refused" } else {
            read.map_or("unattempted", |observation| {
                if let Some(error) = &observation.error {
                    if role == "destination" && error.split(|character: char|
                        !character.is_ascii_alphanumeric() && character != '_')
                        .any(|word| word == "ENOENT") {
                        "conditional-satisfied-absence"
                    } else { "failed" }
                } else if observation.complete && observation.source.is_some() {
                    "conditional-satisfied-read"
                } else { "incomplete" }
            })
        };
        let identity = read.filter(|value| value.error.is_none() && value.complete)
            .and_then(|value| value.source.as_ref())
            .map(|value| crate::source_fetch::sha256_hex(value.as_bytes()));
        let provider_status = read.map(|value| match value.status {
            SourceReadStatus::ReportedSuccess => "reported-success",
            SourceReadStatus::ReportedFailure => "reported-failure",
            SourceReadStatus::Unknown => "unknown",
        });
        json!({"path":path,"role":role,"status":status,"sourceIdentity":identity,
            "providerStatus":provider_status,"providerError":read.and_then(|value|value.error.as_ref()),
            "requiredBy":"maintained-observed-callable-request",
            "requestIdentity":crate::source_fetch::sha256_hex(source.as_bytes())})
    }).collect::<Vec<_>>();
    let unresolved = ledger["needs"]
        .as_array()?
        .iter()
        .filter(|need| !need["kind"].as_str().unwrap_or("").starts_with("read-"))
        .cloned()
        .collect::<Vec<_>>();
    Some(
        json!({"request":{"name":request.name,"parameters":request.parameters,
        "destination":request.destination,"inputs":request.inputs,"acceptance":request.acceptance,
        "command":request.command},"ledger":ledger,"prerequisites":prerequisites,
        "unresolvedNeeds":unresolved,"independentClauses":ledger["clauses"],
        "semanticCoverage":"unbound","declarationAuthority":"conditional-request-classifier",
        "receiptTrust":"requires actual maintained host message boundary","moduleEffects":"unknown",
        "writeAuthority":false,"authored":false,"verified":false}),
    )
}

//! Source-qualified composition; no output literal or unconditional effect authority.
use super::callable_catalog::{observe_source_callables, observed_conditional_graphs};
use super::complete_source_preflight::source_goal_scope;
use super::source_module_identity_port::{SourceModuleIdentityHost, source_operation_module_url};
use crate::seed::parser::{LinoNode, parse_lino};
use crate::source_fetch::sha256_hex;
use serde_json::{Value, json};

fn string<'a>(value: &'a Value, key: &str) -> Result<&'a str, &'static str> {
    value[key].as_str().ok_or("MissingSourceContractField")
}
fn list<'a>(value: &'a Value, key: &str) -> Result<&'a Vec<Value>, &'static str> {
    value[key].as_array().ok_or("MissingSourceContractList")
}
fn require(condition: bool, error: &'static str) -> Result<(), &'static str> {
    if condition { Ok(()) } else { Err(error) }
}
pub fn bind_accepted_import<Host: SourceModuleIdentityHost>(
    host: &Host,
    acceptance: &Value,
    source: &Value,
    exported: &str,
    operation: &Value,
) -> Result<Value, &'static str> {
    require(
        string(operation, "command")?
            == format!("node --test {}", string(operation, "acceptanceOperand")?),
        "DifferentOperation",
    )?;
    require(
        string(operation, "acceptancePath")? == string(acceptance, "path")?,
        "ForeignAcceptance",
    )?;
    let acceptance_identity = sha256_hex(string(acceptance, "content")?.as_bytes());
    require(
        string(operation, "acceptanceIdentity")? == acceptance_identity,
        "AcceptanceDrift",
    )?;
    let source_identity = sha256_hex(string(source, "content")?.as_bytes());
    let catalog =
        observe_source_callables(string(acceptance, "content")?, string(acceptance, "path")?);
    require(
        !list(&catalog, "gaps")?.iter().any(|gap| {
            matches!(
                gap["reason"].as_str(),
                Some("LexicalFailure" | "DuplicateBinding" | "DuplicateExport")
            )
        }),
        "AmbiguousAcceptance",
    )?;
    let source_catalog =
        observe_source_callables(string(source, "content")?, string(source, "path")?);
    let exported_items: Vec<_> = list(&source_catalog, "exports")?
        .iter()
        .filter(|value| value["exposed"] == exported)
        .collect();
    require(exported_items.len() == 1, "UnprovedExport")?;
    require(
        list(&source_catalog, "declarations")?
            .iter()
            .any(|entry| entry["name"] == exported_items[0]["local"]),
        "UnobservedDeclaration",
    )?;
    let module_url = source_operation_module_url(
        Some(host),
        string(source, "path")?,
        string(acceptance, "path")?,
    )?;
    let matching: Vec<_> = list(&catalog, "imports")?
        .iter()
        .filter(|entry| {
            let Some(specifier) = entry["specifier"].as_str() else {
                return false;
            };
            source_operation_module_url(
                Some(host),
                specifier,
                string(acceptance, "path").unwrap_or(""),
            )
            .is_ok_and(|url| url == module_url)
                && entry["bindings"].as_array().is_some_and(|bindings| {
                    bindings
                        .iter()
                        .any(|binding| binding["imported"] == exported)
                })
        })
        .collect();
    require(matching.len() == 1, "NotAlreadyAcceptedImport")?;
    Ok(
        json!({"kind":"accepted-operation-import-reuse","moduleURL":module_url,
        "exported":exported,"sourceIdentity":source_identity,"acceptanceIdentity":catalog["contentId"],
        "operation":operation["command"],"additionalModuleInitialization":false,
        "moduleEffects":source_catalog["moduleEffects"],"callEffects":"conditional",
        "scope":"same-operation-same-module-URL","rustEquivalence":"unknown"}),
    )
}
fn matches_goal(goal: &LinoNode, returned: &[String]) -> bool {
    let lexicon = crate::seed::lexicon();
    goal.children
        .iter()
        .filter(|node| node.name == "lexeme" && node.id == "en")
        .any(|node| {
            node.children
                .iter()
                .filter(|surface| surface.name == "surface")
                .any(|surface| {
                    surface
                        .children
                        .iter()
                        .filter(|text| text.name == "text" && !text.id.is_empty())
                        .any(|text| {
                            returned.iter().any(|clause| {
                                clause.find(&text.id.to_lowercase()).is_some_and(|at| {
                                    !lexicon.mentions_role("statement_negation_cue", &clause[..at])
                                })
                            })
                        })
                })
        })
}
pub fn qualify_seeded_composition<Host: SourceModuleIdentityHost>(
    host: &Host,
    request: &Value,
    observations: &[Value],
    acceptance: &Value,
    operation: &Value,
    seed: &str,
) -> Result<Value, &'static str> {
    let text = string(request, "text")?;
    require(
        string(request, "identity")? == sha256_hex(text.as_bytes()),
        "RequestDrift",
    )?;
    let scope = source_goal_scope(text).ok_or("UnprovedQuotationScope")?;
    let parsed = parse_lino(seed);
    let root = parsed
        .children
        .iter()
        .find(|node| node.name == "source-callable-composition")
        .ok_or("MissingSeededCompositionContract")?;
    let lexicon = crate::seed::lexicon();
    let returned: Vec<_> = crate::obligation_ledger::clauses_with_spans(&scope)
        .into_iter()
        .map(|(text, _)| text.to_lowercase())
        .filter(|text| lexicon.mentions_role("coding_return_action", text))
        .collect();
    let goals: Vec<_> = root
        .children
        .iter()
        .filter(|node| node.name == "goal" && matches_goal(node, &returned))
        .collect();
    require(goals.len() == 1, "UnboundOrAmbiguousSeededGoal")?;
    let goal = goals[0];
    require(
        goal.find_child_value("producer-result") == "optional-record"
            && goal.find_child_value("consumer-result") == "text"
            && goal.find_child_value("absent-result") == "null",
        "UnsupportedGoalShape",
    )?;
    let mut authorized = Vec::new();
    for source in observations {
        let catalog = observe_source_callables(string(source, "content")?, string(source, "path")?);
        for exported in list(&catalog, "exports")? {
            let exposed = string(exported, "exposed")?;
            if let Ok(receipt) = bind_accepted_import(host, acceptance, source, exposed, operation)
            {
                authorized.push((
                    string(source, "path")?.to_owned(),
                    exposed.to_owned(),
                    receipt,
                ));
            }
        }
    }
    let mut candidates = Vec::new();
    for graph in observed_conditional_graphs(observations) {
        if graph["kind"] != "conditional-schema-graph"
            || graph["schemas"]["produced"]["kind"] != "optional"
            || graph["schemas"]["produced"]["value"]["kind"] != "record"
            || graph["schemas"]["result"]["kind"] != "text"
        {
            continue;
        }
        let mut pair = Vec::new();
        for binding in list(&graph, "bindings")? {
            if let Some((_, _, receipt)) = authorized.iter().find(|(path, exported, _)| {
                binding["path"] == *path && binding["exported"] == *exported
            }) {
                pair.push(receipt.clone());
            }
        }
        if pair.len() == list(&graph, "bindings")?.len() {
            candidates.push((graph, pair));
        }
    }
    require(
        candidates.len() == 1,
        "UnprovedOrAmbiguousSourceComposition",
    )?;
    let (graph, imports) = candidates.pop().ok_or("MissingSourceComposition")?;
    Ok(
        json!({"kind":"source-qualified-seeded-composition-candidate","goal":goal.id,
        "graph":graph,"imports":imports,"requestIdentity":request["identity"],
        "goalClauseCoverage":"partial","writeAuthority":false,"authored":false,"verified":false,
        "callEffects":"conditional","moduleEffects":"unknown","rustEquivalence":"unknown"}),
    )
}

//! Seeded lowering of a source graph, never copied source implementations.
use super::callable_catalog::observe_source_callables;
use super::complete_source_preflight::source_goal_scope;
use super::seeded_composition_hook::qualify_seeded_composition;
use super::source_composition_effects::{checked_composition_source, source_null_absence};
use super::source_module_identity_port::SourceModuleIdentityHost;
use crate::seed::parser::parse_lino;
use crate::source_fetch::sha256_hex;
use serde_json::{Value, json};

fn safe(name: &str) -> bool {
    let mut characters = name.chars();
    characters
        .next()
        .is_some_and(|character| character.is_ascii_alphabetic() || matches!(character, '_' | '$'))
        && characters
            .all(|character| character.is_ascii_alphanumeric() || matches!(character, '_' | '$'))
        && !crate::es_tokenizer::is_keyword(name)
        && ![
            "eval",
            "arguments",
            "yield",
            "implements",
            "interface",
            "package",
            "private",
            "protected",
            "public",
            "static",
        ]
        .contains(&name)
}
fn fill(text: &str, slots: &[(&str, String)]) -> Result<String, &'static str> {
    let names = regex::Regex::new(r"\{([a-z]+(?:-[a-z]+)*)\}").map_err(|_| "InvalidSlotGrammar")?;
    if names
        .captures_iter(text)
        .any(|capture| !slots.iter().any(|(name, _)| *name == &capture[1]))
    {
        return Err("UnknownTemplateSlot");
    }
    Ok(slots.iter().fold(text.to_owned(), |text, (name, value)| {
        text.replace(&format!("{{{name}}}"), value)
    }))
}
fn observed_declaration(observations: &[Value], binding: &Value) -> Result<Value, &'static str> {
    let source = observations
        .iter()
        .find(|source| source["path"] == binding["path"])
        .ok_or("UnknownSourceModule")?;
    let catalog = observe_source_callables(
        source["content"].as_str().ok_or("MissingSourceBytes")?,
        source["path"].as_str().ok_or("MissingSourcePath")?,
    );
    let exported = catalog["exports"]
        .as_array()
        .ok_or("MissingSourceExports")?
        .iter()
        .find(|value| value["exposed"] == binding["exported"])
        .ok_or("UnknownSourceExport")?;
    catalog["declarations"]
        .as_array()
        .ok_or("MissingSourceDeclarations")?
        .iter()
        .find(|value| value["name"] == exported["local"])
        .cloned()
        .ok_or("UnobservedDeclaration")
}
pub fn derive_seeded_source_plan<Host: SourceModuleIdentityHost>(
    host: &Host,
    request: &Value,
    observations: &[Value],
    acceptance: &Value,
    operation: &Value,
    seed: &str,
) -> Result<Value, &'static str> {
    let name = request["name"].as_str().ok_or("UnsupportedDeclaration")?;
    let parameters = request["parameters"]
        .as_array()
        .filter(|values| values.len() == 1)
        .ok_or("UnsupportedDeclaration")?;
    let parameter = parameters[0].as_str().ok_or("UnsupportedDeclaration")?;
    if !safe(name) || !safe(parameter) {
        return Err("UnsupportedDeclaration");
    }
    let mut candidate =
        qualify_seeded_composition(host, request, observations, acceptance, operation, seed)?;
    let parsed = parse_lino(seed);
    let root = parsed
        .children
        .iter()
        .find(|node| node.name == "source-callable-composition")
        .ok_or("MissingCompositionSeed")?;
    let goal = root
        .children
        .iter()
        .find(|node| node.name == "goal" && candidate["goal"] == node.id)
        .ok_or("MissingSeededGoal")?;
    let bindings = candidate["graph"]["bindings"]
        .as_array()
        .filter(|values| values.len() == 2)
        .ok_or("UnsupportedGraphBindings")?;
    let consumer = observed_declaration(observations, &bindings[1])?;
    let consumer_parameters = consumer["parameters"]
        .as_array()
        .filter(|values| values.len() == 1)
        .ok_or("UnknownConsumerArity")?;
    let consumer_parameter = consumer_parameters[0]
        .as_str()
        .ok_or("UnsupportedConsumerParameter")?;
    if !safe(consumer_parameter) {
        return Err("UnsupportedConsumerParameter");
    }
    let lexemes: Vec<_> = goal
        .children
        .iter()
        .filter(|node| node.name == "lexeme" && node.id == "en")
        .flat_map(|node| {
            node.children
                .iter()
                .filter(|surface| surface.name == "surface")
        })
        .flat_map(|surface| surface.children.iter().filter(|value| value.name == "text"))
        .map(|value| regex::escape(&value.id))
        .collect();
    let styles: Vec<_> = goal
        .children
        .iter()
        .filter(|node| node.name == "style")
        .map(|node| regex::escape(node.find_child_value("surface")))
        .collect();
    let slots = [
        ("style", format!("(?:{})?", styles.join("|"))),
        ("goal", format!("(?:{})", lexemes.join("|"))),
        ("consumer-parameter", regex::escape(consumer_parameter)),
        ("wrapper-parameter", regex::escape(parameter)),
    ];
    let scope = source_goal_scope(request["text"].as_str().ok_or("MissingRequestBytes")?)
        .ok_or("UnprovedQuotationScope")?;
    let sentences = crate::agentic_coding::shell_command_policy::sentences(&scope);
    let mut matches = Vec::new();
    for form in goal.children.iter().filter(|node| node.name == "form") {
        let mut qualified_pattern = form.find_child_value("pattern").to_owned();
        let mut technical_captures = Vec::new();
        loop {
            let next = [
                ("consumer-parameter", consumer_parameter),
                ("wrapper-parameter", parameter),
            ]
            .into_iter()
            .filter_map(|(role, expected)| {
                let marker = format!("{{{role}}}");
                qualified_pattern
                    .find(&marker)
                    .map(|start| (start, marker, expected))
            })
            .min_by_key(|(start, _, _)| *start);
            let Some((start, marker, expected)) = next else {
                break;
            };
            let capture_name = format!("sourceParameter{}", technical_captures.len());
            qualified_pattern.replace_range(
                start..start + marker.len(),
                &format!("(?<{capture_name}>{})", regex::escape(expected)),
            );
            technical_captures.push((capture_name, expected));
        }
        let pattern = fill(&qualified_pattern, &slots)?;
        let expression = regex::RegexBuilder::new(&pattern)
            .case_insensitive(true)
            .build()
            .map_err(|_| "InvalidReturnForm")?;
        for sentence in &sentences {
            if expression.captures(sentence.text).is_some_and(|captures| {
                technical_captures.iter().all(|(name, expected)| {
                    captures
                        .name(name)
                        .is_some_and(|matched| matched.as_str() == *expected)
                })
            }) {
                matches.push(json!({"form":form.id,"sentence":sentence.text}));
            }
        }
    }
    if matches.len() != 1 {
        return Err("UnprovedCompleteReturnForm");
    }
    let mut locals = std::collections::BTreeSet::from([name.to_owned(), parameter.to_owned()]);
    let mut fresh = |base: &str| {
        let mut name = base.to_owned();
        let mut index = 0;
        while locals.contains(&name) {
            index += 1;
            name = format!("{base}{index}");
        }
        locals.insert(name.clone());
        name
    };
    let producer_local = fresh("_sourceProjection");
    let consumer_local = fresh("_sourceRendering");
    let value_local = fresh("_sourceValue");
    let templates: Vec<_> = goal
        .children
        .iter()
        .filter(|node| node.name == "template")
        .collect();
    if templates.len() != 1 || templates[0].find_child_value("text").is_empty() {
        return Err("AmbiguousSourceTemplate");
    }
    let imports = candidate["imports"]
        .as_array()
        .filter(|values| values.len() == 2)
        .ok_or("UnsupportedImportBindings")?;
    if !imports
        .iter()
        .all(|value| value["exported"].as_str().is_some_and(safe))
    {
        return Err("UnsupportedImportBinding");
    }
    let producer = observed_declaration(observations, &bindings[0])?;
    if !source_null_absence(&producer["contract"]["conditionalIR"]) {
        return Err("UndefinedAbsenceIsNotNull");
    }
    let source = fill(
        templates[0].find_child_value("text"),
        &[
            (
                "producer-export",
                imports[0]["exported"]
                    .as_str()
                    .ok_or("MissingExport")?
                    .to_owned(),
            ),
            ("producer-local", producer_local),
            (
                "producer-url",
                serde_json::to_string(&imports[0]["moduleURL"])
                    .map_err(|_| "UnencodableModuleURL")?,
            ),
            (
                "consumer-export",
                imports[1]["exported"]
                    .as_str()
                    .ok_or("MissingExport")?
                    .to_owned(),
            ),
            ("consumer-local", consumer_local),
            (
                "consumer-url",
                serde_json::to_string(&imports[1]["moduleURL"])
                    .map_err(|_| "UnencodableModuleURL")?,
            ),
            ("name", name.to_owned()),
            ("parameter", parameter.to_owned()),
            ("value-local", value_local),
        ],
    )?;
    let effects = checked_composition_source(&source, request, imports)?;
    let fields = candidate.as_object_mut().ok_or("MissingCandidateObject")?;
    let observed_request = super::discovery::observed_callable_request(
        request["text"].as_str().ok_or("MissingRequestBytes")?,
    )
    .ok_or("UnboundCallableRequest")?;
    let user_message =
        crate::protocol::ChatMessage::user(request["text"].as_str().ok_or("MissingRequestBytes")?);
    fields.insert(
        "goalLedger".to_owned(),
        super::discovery::observed_callable_goal_ledger(&observed_request, &[user_message]),
    );
    fields.insert("effectPlan".to_owned(), effects);
    fields.insert("kind".to_owned(), json!("seeded-source-composition-plan"));
    fields.insert(
        "sourceIdentity".to_owned(),
        json!(sha256_hex(source.as_bytes())),
    );
    fields.insert("source".to_owned(), json!(source));
    fields.insert(
        "seedIdentity".to_owned(),
        json!(sha256_hex(seed.as_bytes())),
    );
    fields.insert(
        "goalClauseCoverage".to_owned(),
        json!("complete-seeded-return-form"),
    );
    fields.insert(
        "returnForm".to_owned(),
        matches.pop().ok_or("MissingReturnForm")?,
    );
    fields.insert(
        "effectAuthorization".to_owned(),
        json!("unproved-complete-Needs"),
    );
    fields.insert("verification".to_owned(), json!("not-executed"));
    fields.insert(
        "profile".to_owned(),
        json!("conditional JavaScript source-owned plain data; caller effects inherited, not pure"),
    );
    Ok(candidate)
}

//! Close operation inventory over imported source graph; called effects remain conditional.
use super::source_contract::text;
use serde_json::{Value, json};
fn same(node: &Value, expected: &str) -> Result<(), &'static str> {
    if text(node) == expected {
        Ok(())
    } else {
        Err("UnexpectedSourceOperation")
    }
}
fn group<'source>(
    node: &'source Value,
    delimiter: &str,
) -> Result<&'source Vec<Value>, &'static str> {
    if node["$"] != "group" || node["delim"] != delimiter {
        return Err("UnexpectedSourceGroup");
    }
    node["trees"].as_array().ok_or("MissingSourceGroup")
}
pub fn checked_composition_source(
    source: &str,
    request: &Value,
    imports: &[Value],
) -> Result<Value, &'static str> {
    let raw = crate::es_tokenizer::tokenize(source).map_err(|_| "SourceLexicalFailure")?;
    let trees: Vec<_> = raw
        .iter()
        .map(super::callable_catalog::tree_value)
        .collect();
    if trees.len() != 15 || imports.len() != 2 {
        return Err("ExtraModuleOperation");
    }
    let parameter = request["parameters"]
        .as_array()
        .filter(|value| value.len() == 1)
        .and_then(|value| value[0].as_str())
        .ok_or("UnsupportedDeclaration")?;
    let name = request["name"].as_str().ok_or("UnsupportedDeclaration")?;
    let mut locals = Vec::new();
    for (index, imported) in imports.iter().enumerate() {
        let at = index * 5;
        same(&trees[at], "import")?;
        let binding = group(&trees[at + 1], "brace")?;
        if binding.len() != 3 {
            return Err("UnknownImportBinding");
        }
        same(
            &binding[0],
            imported["exported"]
                .as_str()
                .ok_or("MissingExportBinding")?,
        )?;
        same(&binding[1], "as")?;
        if binding[2]["kind"] != "identifier" {
            return Err("UnsupportedLocalBinding");
        }
        locals.push(text(&binding[2]).to_owned());
        same(&trees[at + 2], "from")?;
        if trees[at + 3]["kind"] != "string" {
            return Err("UnsupportedImportURL");
        }
        let parsed: Value =
            serde_json::from_str(text(&trees[at + 3])).map_err(|_| "UnsupportedImportURL")?;
        if parsed != imported["moduleURL"] {
            return Err("ForeignImportURL");
        }
        same(&trees[at + 4], ";")?;
    }
    same(&trees[10], "export")?;
    same(&trees[11], "function")?;
    same(&trees[12], name)?;
    let parameters = group(&trees[13], "paren")?;
    if parameters.len() != 1 {
        return Err("UnsupportedDeclaration");
    }
    same(&parameters[0], parameter)?;
    let body = group(&trees[14], "brace")?;
    if body.len() != 16 {
        return Err("ExtraFunctionOperation");
    }
    same(&body[0], "const")?;
    if body[1]["kind"] != "identifier" {
        return Err("UnsupportedLocalBinding");
    }
    let selected = text(&body[1]);
    let unique = [
        locals[0].as_str(),
        locals[1].as_str(),
        selected,
        name,
        parameter,
    ]
    .into_iter()
    .collect::<std::collections::BTreeSet<_>>();
    if unique.len() != 5 {
        return Err("BindingCollision");
    }
    same(&body[2], "=")?;
    same(&body[3], &locals[0])?;
    let arguments = group(&body[4], "paren")?;
    if arguments.len() != 1 {
        return Err("UnsupportedSourceCall");
    }
    same(&arguments[0], parameter)?;
    same(&body[5], ";")?;
    same(&body[6], "return")?;
    same(&body[7], selected)?;
    same(&body[8], "===")?;
    same(&body[9], "null")?;
    same(&body[10], "?")?;
    same(&body[11], "null")?;
    same(&body[12], ":")?;
    same(&body[13], &locals[1])?;
    let arguments = group(&body[14], "paren")?;
    if arguments.len() != 1 {
        return Err("UnsupportedSourceCall");
    }
    same(&arguments[0], selected)?;
    same(&body[15], ";")?;
    Ok(
        json!({"kind":"checked-source-import-composition","imports":imports.iter().map(|value|
        json!({"moduleURL":value["moduleURL"],"exported":value["exported"],"sourceIdentity":value["sourceIdentity"]}))
        .collect::<Vec<_>>(),"calls":[{"source":0,"argument":parameter,"result":selected},
        {"source":1,"argument":selected,"guard":"nonnull"}],"output":{"absent":null,"present":"source-call-1"},
        "localMutation":false,"additionalModuleInitialization":false,
        "calledSourceEffects":"conditional; inherited, not pure","scope":"same declared Node acceptance operation"}),
    )
}
#[must_use]
pub fn source_null_absence(ir: &Value) -> bool {
    fn proven(node: &Value) -> bool {
        node["op"] == "literal" && node.get("value").is_some_and(Value::is_null)
            || node["op"] == "??"
                && node["right"]["op"] == "literal"
                && node["right"].get("value").is_some_and(Value::is_null)
            || node["op"] == "conditional" && proven(&node["yes"]) && proven(&node["no"])
    }
    ir["status"] == "parsed"
        && ir["ir"].as_array().is_some_and(|statements| {
            statements.len() == 1
                && statements[0]["op"] == "return"
                && proven(&statements[0]["value"])
        })
}

//! Host module identity resolution; no authoring or runtime-effect authority.
pub trait SourceModuleIdentityHost {
    fn module_url(&self, specifier: &str, parent: &str) -> Result<String, &'static str>;
}
pub fn source_operation_module_url<Host: SourceModuleIdentityHost>(
    host: Option<&Host>,
    specifier: &str,
    parent: &str,
) -> Result<String, &'static str> {
    host.ok_or("MissingSourceModuleIdentityHost")?
        .module_url(specifier, parent)
}

//! Native source consumer over maintained Read history and trusted host/IO ports.
use super::complete_source_preflight::{
    bind_complete_source_needs, derive_complete_source_request,
};
use super::seeded_source_plan::derive_seeded_source_plan;
use super::source_module_identity_port::SourceModuleIdentityHost;
use super::source_need_preflight::source_need_preflight;
use super::source_operation_transaction::{
    CandidateIo, CandidateTransaction, SourceOperationHost, create_candidate_transaction,
};
use crate::agentic_coding::{
    planner::{self, AgenticPlan},
    progress::Progress,
};
use crate::protocol::ChatMessage;
use crate::source_fetch::sha256_hex;
use serde_json::{Value, json};

/// Only the installed host supplies operation metadata and authored grammar.
pub trait SourceCompositionHost: SourceOperationHost + SourceModuleIdentityHost {
    fn request_seed(&self) -> &str;
    fn composition_seed(&self) -> &str;
    fn operation_descriptor(
        &self,
        receipt: &Self::Receipt,
        request: &str,
        command: &str,
        workspace: &str,
    ) -> Result<Value, &'static str>;
}
pub struct PreparedSourceCandidate<'io, Io: CandidateIo> {
    source_identity: String,
    request_text: String,
    command: String,
    workspace: String,
    destination: String,
    pub plan: AgenticPlan,
    pub composition: Value,
    pub conditional_proof: Value,
    pub transaction: CandidateTransaction<'io, Io>,
}
/// Missing hosts, incomplete Reads, unknown Needs and unowned destinations refuse before Write.
pub fn prepare_source_candidate<'io, Host: SourceCompositionHost, Io: CandidateIo>(
    host: Option<&Host>,
    io: &'io mut Io,
    receipt: &Host::Receipt,
    request_text: &str,
    messages: &[ChatMessage],
    workspace: &str,
    tool_names: &[&str],
) -> Result<PreparedSourceCandidate<'io, Io>, &'static str> {
    let host = host.ok_or("MissingSourceOperationHost")?;
    let write_tool =
        crate::agentic_coding::capability_router::tool_for(tool_names, planner::Capability::Write)
            .ok_or("MissingWriteTool")?;
    let frame = derive_complete_source_request(request_text, host.request_seed())
        .ok_or("UnboundCompleteSourceRequest")?;
    let preflight =
        source_need_preflight(request_text, messages).ok_or("UnboundSourceReadHistory")?;
    if !preflight["prerequisites"].as_array().is_some_and(|values| {
        values.iter().all(|value| {
            matches!(
                value["status"].as_str(),
                Some("conditional-satisfied-read" | "conditional-satisfied-absence")
            )
        })
    }) {
        return Err("UnsolvedImmutableReadPrerequisite");
    }
    if !preflight["prerequisites"].as_array().is_some_and(|values| {
        values.iter().any(|value| {
            value["role"] == "destination" && value["status"] == "conditional-satisfied-absence"
        })
    }) {
        return Err("UnprovedDestinationMerge");
    }
    let request = &frame["request"];
    let command = request["command"]
        .as_str()
        .ok_or("MissingAcceptedCommand")?;
    let canonical_sources = host.accepted_sources(receipt, request_text, command, workspace)?;
    let operation = host.operation_descriptor(receipt, request_text, command, workspace)?;
    let progress = Progress::scan(messages);
    let inputs = request["inputs"].as_array().ok_or("MissingSourceInputs")?;
    let mut observations = Vec::new();
    for input in inputs {
        let path = input.as_str().ok_or("MissingSourcePath")?;
        let read = progress.source_read_for(path).ok_or("MissingSourceRead")?;
        let bytes = read
            .source
            .as_ref()
            .filter(|_| read.complete && read.error.is_none())
            .ok_or("IncompleteSourceRead")?;
        let identity = sha256_hex(bytes.as_bytes());
        let matching: Vec<_> = canonical_sources
            .iter()
            .filter(|source| source["sha256"] == identity && source["content"] == *bytes)
            .collect();
        if matching.len() != 1 {
            return Err("AmbiguousCanonicalSourceCorrespondence");
        }
        observations.push(json!({"path":matching[0]["path"],"content":bytes}));
    }
    let acceptance_paths = request["acceptance"]
        .as_array()
        .filter(|paths| paths.len() == 1)
        .ok_or("AmbiguousAcceptance")?;
    let acceptance_path = acceptance_paths[0]
        .as_str()
        .ok_or("MissingAcceptancePath")?;
    let acceptance_read = progress
        .source_read_for(acceptance_path)
        .ok_or("MissingAcceptanceRead")?;
    let acceptance_bytes = acceptance_read
        .source
        .as_ref()
        .filter(|_| acceptance_read.complete && acceptance_read.error.is_none())
        .ok_or("IncompleteAcceptanceRead")?;
    let acceptance = json!({"path":acceptance_path,"content":acceptance_bytes});
    let mut qualified_request = request.clone();
    let fields = qualified_request
        .as_object_mut()
        .ok_or("MissingRequestObject")?;
    fields.insert("text".to_owned(), json!(request_text));
    fields.insert("identity".to_owned(), frame["requestIdentity"].clone());
    let composition = derive_seeded_source_plan(
        host,
        &qualified_request,
        &observations,
        &acceptance,
        &operation,
        host.composition_seed(),
    )?;
    let conditional_proof =
        bind_complete_source_needs(&frame, &composition, &preflight, &canonical_sources)?;
    // Revalidate the same private receipt after every source-derived contract calculation.
    if host.accepted_sources(receipt, request_text, command, workspace)? != canonical_sources {
        return Err("CanonicalSourceDrift");
    }
    let destination = request["destination"]
        .as_str()
        .ok_or("MissingDestination")?;
    let source = composition["source"]
        .as_str()
        .ok_or("MissingComposedSource")?;
    let identity = sha256_hex(source.as_bytes());
    let transaction = create_candidate_transaction(io, destination.to_owned(), identity.clone())?;
    let plan = planner::plan_one(
        write_tool,
        json!({"path":destination,"content":source}).to_string(),
    );
    Ok(PreparedSourceCandidate {
        source_identity: identity,
        request_text: request_text.to_owned(),
        command: command.to_owned(),
        workspace: workspace.to_owned(),
        destination: destination.to_owned(),
        plan,
        composition,
        conditional_proof,
        transaction,
    })
}

/// Consume only trusted candidate-bound status; public success prose remains unverified.
pub fn finish_source_candidate<Host, Io>(
    host: Option<&Host>,
    prepared: &mut PreparedSourceCandidate<'_, Io>,
    receipt: &Host::Receipt,
    process_receipt: &Io::Receipt,
) -> Result<Value, &'static str>
where
    Host: super::source_operation_transaction::SourceCandidateOperationHost,
    Io: CandidateIo,
{
    let identity = &prepared.source_identity;
    let status = host.ok_or("MissingSourceOperationHost").and_then(|host| {
        host.candidate_status(
            receipt,
            &prepared.request_text,
            &prepared.command,
            &prepared.workspace,
            &prepared.destination,
            identity,
        )
    });
    match status {
        Ok(Some(0)) => {
            let disposition = match prepared.transaction.finish(process_receipt) {
                Ok(disposition) => disposition,
                Err(error) => {
                    let rollback = prepared.transaction.abort()?;
                    return Ok(json!({"authored":true,"verified":false,"ownedStatus":0,
                        "verificationFailure":error,"physicalDisposition":rollback,
                        "universalEffectsProved":false}));
                }
            };
            let verified = disposition["state"] == "committed";
            Ok(json!({"authored":true,"verified":verified,"ownedStatus":0,
                "physicalDisposition":disposition,"universalEffectsProved":false}))
        }
        observation => {
            let disposition = prepared.transaction.abort()?;
            Ok(json!({"authored":true,"verified":false,
                "ownedStatus":observation.as_ref().ok().copied().flatten(),
                "verificationFailure":observation.err(),"physicalDisposition":disposition,
                "universalEffectsProved":false}))
        }
    }
}

/// Mirrors recordPreparedSourceWrite; no caller metadata can create this transaction.
pub fn authorize_source_candidate_write<Io: CandidateIo>(
    prepared: &PreparedSourceCandidate<'_, Io>,
) -> Result<Value, &'static str> {
    prepared.transaction.authorize_write()
}
pub fn record_prepared_source_write<Io: CandidateIo>(
    prepared: &mut PreparedSourceCandidate<'_, Io>,
) -> Result<Value, &'static str> {
    prepared.transaction.record_write()
}

/// Mirrors abortSourceCandidate: receipt absence is unverified, not successful execution.
pub fn abort_source_candidate<Io: CandidateIo>(
    prepared: &mut PreparedSourceCandidate<'_, Io>,
) -> Result<Value, &'static str> {
    let disposition = prepared.transaction.abort()?;
    Ok(json!({"authored":true,"verified":false,"ownedStatus":null,
       "verificationFailure":"MissingOwnedVerificationReceipt","physicalDisposition":disposition,
       "universalEffectsProved":false}))
}

/// Trusted execution callbacks consume the same private prepared transaction as the JavaScript session.
pub struct SourceCandidateContext<'context> {
    pub request: &'context str,
    pub messages: &'context [ChatMessage],
    pub workspace: &'context str,
    pub tools: &'context [&'context str],
}
pub fn execute_source_candidate<Host, Io, Write, Verify>(
    host: Option<&Host>,
    io: &mut Io,
    receipt: &Host::Receipt,
    context: SourceCandidateContext<'_>,
    mut execute_write: Write,
    mut execute_verification: Verify,
) -> Result<Value, &'static str>
where
    Host: SourceCompositionHost + super::source_operation_transaction::SourceCandidateOperationHost,
    Io: CandidateIo,
    Write: FnMut(&AgenticPlan) -> Result<(), &'static str>,
    Verify: FnMut(&str, &str) -> Result<(Host::Receipt, Io::Receipt), &'static str>,
{
    let SourceCandidateContext {
        request,
        messages,
        workspace,
        tools,
    } = context;
    let mut prepared =
        prepare_source_candidate(host, io, receipt, request, messages, workspace, tools)?;
    authorize_source_candidate_write(&prepared)?;
    if let Err(error) = execute_write(&prepared.plan) {
        record_prepared_source_write(&mut prepared).map_err(|_| "UnownedWriteFailure")?;
        let mut outcome = abort_source_candidate(&mut prepared)?;
        outcome["executionFailure"] = json!(error);
        return Ok(outcome);
    }
    record_prepared_source_write(&mut prepared)?;
    let verification = execute_verification(&prepared.command, &prepared.workspace);
    match verification {
        Ok((after, process)) => finish_source_candidate(host, &mut prepared, &after, &process),
        Err(error) => {
            let mut outcome = abort_source_candidate(&mut prepared)?;
            outcome["executionFailure"] = json!(error);
            Ok(outcome)
        }
    }
}

//! Host-owned source receipt and reversible candidate ports; no filesystem/process imports.
use serde_json::Value;

/// Implementations are trusted host boundaries, never caller message metadata.
pub trait SourceOperationHost {
    type Receipt;
    fn accepted_sources(
        &self,
        receipt: &Self::Receipt,
        request: &str,
        command: &str,
        workspace: &str,
    ) -> Result<Vec<Value>, &'static str>;
}
/// Mirrors acceptedOperationSourceBytes: absent hosts refuse instead of inventing evidence.
pub fn accepted_operation_source_bytes<Host: SourceOperationHost>(
    host: Option<&Host>,
    receipt: &Host::Receipt,
    request: &str,
    command: &str,
    workspace: &str,
) -> Result<Vec<Value>, &'static str> {
    host.ok_or("MissingSourceOperationHost")?
        .accepted_sources(receipt, request, command, workspace)
}

/// Candidate proof is bound to bytes before/after the actual operation and at consumption.
pub trait SourceCandidateOperationHost: SourceOperationHost {
    fn candidate_status(
        &self,
        receipt: &Self::Receipt,
        request: &str,
        command: &str,
        workspace: &str,
        destination: &str,
        identity: &str,
    ) -> Result<Option<i32>, &'static str>;
}
/// Final delivery requires owned IO completion in addition to an accepted process receipt.
pub trait SourceFinalizedCandidateOperationHost: SourceCandidateOperationHost {
    fn finalized_candidate_status(
        &self,
        receipt: &Self::Receipt,
        request: &str,
        command: &str,
        workspace: &str,
        destination: &str,
        identity: &str,
    ) -> Result<Option<i32>, &'static str>;
}
/// Mirrors acceptedOperationCandidateStatus; caller text cannot manufacture status.
pub fn accepted_operation_candidate_status<Host: SourceFinalizedCandidateOperationHost>(
    host: Option<&Host>,
    receipt: &Host::Receipt,
    request: &str,
    command: &str,
    workspace: &str,
    destination: &str,
    identity: &str,
) -> Result<Option<i32>, &'static str> {
    host.ok_or("MissingSourceOperationHost")?
        .finalized_candidate_status(receipt, request, command, workspace, destination, identity)
}

#[derive(PartialEq)]
pub enum CandidateFile {
    Absent,
    File(String),
    Other,
}
pub enum ProcessDisposition {
    Succeeded,
    Failed,
    Incomplete,
}
pub trait CandidateIo {
    type Receipt;
    fn owns_lease(&self) -> bool;
    fn inspect(&self, path: &str) -> CandidateFile;
    fn process_disposition(
        &self,
        receipt: &Self::Receipt,
    ) -> Result<ProcessDisposition, &'static str>;
    fn remove_unchanged_candidate(&mut self, path: &str, identity: &str) -> bool;
}
pub struct CandidateTransaction<'host, Io: CandidateIo> {
    io: &'host mut Io,
    path: String,
    identity: String,
    phase: &'static str,
}
/// Mirrors createCandidateTransaction; the IO provider owns both lease and receipts.
pub fn create_candidate_transaction<Io: CandidateIo>(
    io: &mut Io,
    path: String,
    identity: String,
) -> Result<CandidateTransaction<'_, Io>, &'static str> {
    if !io.owns_lease() {
        return Err("MissingSingleWriterLease");
    }
    if io.inspect(&path) != CandidateFile::Absent {
        return Err("UnownedExistingDestination");
    }
    Ok(CandidateTransaction {
        io,
        path,
        identity,
        phase: "prepared",
    })
}
impl<Io: CandidateIo> CandidateTransaction<'_, Io> {
    fn unchanged(&self) -> bool {
        self.io.inspect(&self.path) == CandidateFile::File(self.identity.clone())
    }
    pub fn authorize_write(&self) -> Result<Value, &'static str> {
        if self.phase != "prepared" {
            return Err("InvalidCandidatePhase");
        }
        if !self.io.owns_lease() {
            return Err("MissingSingleWriterLease");
        }
        if self.io.inspect(&self.path) != CandidateFile::Absent {
            return Err("UnownedExistingDestination");
        }
        Ok(serde_json::json!({"state":self.phase,"authorized":true}))
    }
    pub fn record_write(&mut self) -> Result<Value, &'static str> {
        if !self.io.owns_lease() {
            return Err("MissingSingleWriterLease");
        }
        if self.phase != "prepared" {
            return Err("InvalidCandidatePhase");
        }
        if !self.unchanged() {
            return Err("UnobservedCandidateWrite");
        }
        self.phase = "written";
        Ok(serde_json::json!({"state":self.phase,"removed":false}))
    }
    /// Remove only the unchanged owned candidate without claiming any process ran.
    pub fn abort(&mut self) -> Result<Value, &'static str> {
        if self.phase != "written" {
            return Err("InvalidCandidatePhase");
        }
        if !self.io.owns_lease() {
            return Err("MissingSingleWriterLease");
        }
        if !self.unchanged() {
            self.phase = "refused-drift";
            return Ok(serde_json::json!({"state":self.phase,"removed":false}));
        }
        let removed = self
            .io
            .remove_unchanged_candidate(&self.path, &self.identity);
        self.phase = if removed {
            "rolled-back"
        } else {
            "refused-drift"
        };
        Ok(
            serde_json::json!({"state":self.phase,"removed":removed,"processDisposition":"unverified"}),
        )
    }
    pub fn finish(&mut self, receipt: &Io::Receipt) -> Result<Value, &'static str> {
        if self.phase != "written" {
            return Err("InvalidCandidatePhase");
        }
        if !self.io.owns_lease() {
            return Err("MissingSingleWriterLease");
        }
        let disposition = self.io.process_disposition(receipt)?;
        if !self.unchanged() {
            self.phase = "refused-drift";
            return Ok(serde_json::json!({"state":self.phase,"removed":false}));
        }
        if matches!(disposition, ProcessDisposition::Succeeded) {
            self.phase = "committed";
            return Ok(serde_json::json!({"state":self.phase,"removed":false}));
        }
        let removed = self
            .io
            .remove_unchanged_candidate(&self.path, &self.identity);
        self.phase = if removed {
            "rolled-back"
        } else {
            "refused-drift"
        };
        Ok(serde_json::json!({"state":self.phase,"removed":removed}))
    }
}

#[cfg(test)]
mod finalized_operation_tests {
    use super::*;
    use std::rc::Rc;

    struct Receipt(Rc<()>);
    struct ProofHost {
        owned: Rc<()>,
        finalized: bool,
    }
    impl SourceOperationHost for ProofHost {
        type Receipt = Receipt;
        fn accepted_sources(
            &self,
            receipt: &Receipt,
            _request: &str,
            _command: &str,
            _workspace: &str,
        ) -> Result<Vec<Value>, &'static str> {
            if !Rc::ptr_eq(&self.owned, &receipt.0) {
                return Err("UnownedProcessReceipt");
            }
            Ok(Vec::new())
        }
    }
    impl SourceCandidateOperationHost for ProofHost {
        fn candidate_status(
            &self,
            receipt: &Receipt,
            request: &str,
            command: &str,
            workspace: &str,
            _destination: &str,
            _identity: &str,
        ) -> Result<Option<i32>, &'static str> {
            self.accepted_sources(receipt, request, command, workspace)?;
            Ok(Some(0))
        }
    }
    impl SourceFinalizedCandidateOperationHost for ProofHost {
        fn finalized_candidate_status(
            &self,
            receipt: &Receipt,
            request: &str,
            command: &str,
            workspace: &str,
            destination: &str,
            identity: &str,
        ) -> Result<Option<i32>, &'static str> {
            let status =
                self.candidate_status(receipt, request, command, workspace, destination, identity)?;
            Ok(if self.finalized { status } else { None })
        }
    }
    #[test]
    fn successful_process_requires_finalized_ownership() {
        let owned = Rc::new(());
        let receipt = Receipt(Rc::clone(&owned));
        let mut host = ProofHost {
            owned,
            finalized: false,
        };
        assert_eq!(
            host.candidate_status(
                &receipt,
                "request",
                "command",
                "workspace",
                "destination",
                "identity"
            ),
            Ok(Some(0))
        );
        assert_eq!(
            accepted_operation_candidate_status(
                Some(&host),
                &receipt,
                "request",
                "command",
                "workspace",
                "destination",
                "identity"
            ),
            Ok(None)
        );
        host.finalized = true;
        assert_eq!(
            accepted_operation_candidate_status(
                Some(&host),
                &receipt,
                "request",
                "command",
                "workspace",
                "destination",
                "identity"
            ),
            Ok(Some(0))
        );
    }
    #[test]
    fn absent_host_and_foreign_receipt_refuse() {
        let host = ProofHost {
            owned: Rc::new(()),
            finalized: true,
        };
        let foreign = Receipt(Rc::new(()));
        assert_eq!(
            accepted_operation_candidate_status::<ProofHost>(
                None,
                &foreign,
                "request",
                "command",
                "workspace",
                "destination",
                "identity"
            ),
            Err("MissingSourceOperationHost")
        );
        assert_eq!(
            accepted_operation_candidate_status(
                Some(&host),
                &foreign,
                "request",
                "command",
                "workspace",
                "destination",
                "identity"
            ),
            Err("UnownedProcessReceipt")
        );
    }
}

//! Source-owned diagnostic rendering; no request or effect authorization.
use crate::seed::parser::parse_lino;
const MEANINGS: &str =
    include_str!("../../embedded/data/seed/meanings-source-authoring-grammar.lino");
pub fn source_contract_diagnostic(code: &str, language: &str) -> Option<String> {
    let root = parse_lino(MEANINGS);
    let meanings: Vec<_> = root
        .children
        .iter()
        .filter(|node| node.name == "meanings")
        .collect();
    if meanings.len() != 1 {
        return None;
    }
    let records: Vec<_> = meanings[0]
        .children
        .iter()
        .filter(|node| {
            node.name == code && node.find_child_value("role") == "source-contract-diagnostic"
        })
        .collect();
    if records.len() != 1 {
        return None;
    }
    let lexemes: Vec<_> = records[0]
        .children
        .iter()
        .filter(|node| node.name == "lexeme" && node.id == language)
        .collect();
    if lexemes.len() != 1 {
        return None;
    }
    let surfaces: Vec<_> = lexemes[0]
        .children
        .iter()
        .filter(|node| node.name == "surface")
        .collect();
    if surfaces.len() != 1 {
        return None;
    }
    let text = surfaces[0].find_child_value("text");
    (!text.is_empty()).then(|| text.to_owned())
}

